  Lemma seg_L5b : forall regs mem (pp : word) (A len cap : Z) K,
    read_ret_regs regs pp A len cap (Z_to_bv 64 0) ->
    stk_ok RSEGS mem (Z_to_bv 64 (bv_unsigned sp0 - 128)) MSTK -> ro_none mem ->
    rdn RSEGS mem (Z_to_bv 64 (bv_unsigned sp0 - 136)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0x2bbd4)) ->
    (forall regs' mem',
        getr regs' 1 = Z_to_bv 64 0x7d224 -> getr regs' 2 = Z_to_bv 64 (bv_unsigned sp0 - 144) -> getr regs' 4 = Z_to_bv 64 0x96970 ->
        getr regs' 8 = Z_to_bv 64 2 -> getr regs' 9 = Z_to_bv 64 A -> getr regs' 10 = Z_to_bv 64 3 -> getr regs' 17 = Z_to_bv 64 57 ->
        getr regs' 18 = pp -> getr regs' 19 = Z_to_bv 64 len -> getr regs' 20 = Z_to_bv 64 3 -> getr regs' 21 = Z_to_bv 64 cap ->
        getr regs' 22 = Z_to_bv 64 0x84f89 ->
        frame_mod mem mem' (regL_w sp0) -> stk_ok RSEGS mem' (Z_to_bv 64 (bv_unsigned sp0 - 128)) MSTK ->
        rdn RSEGS mem' (Z_to_bv 64 (bv_unsigned sp0 - 136)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0x2bbe8)) ->
        realizes RSEGS (mkCfg (mkst regs' (Z_to_bv 64 0x7a2a4) mem' (seg_rom RSEGS)) model) K) ->
    realizes RSEGS (mkCfg (mkst regs (Z_to_bv 64 0x7a2a8) mem (seg_rom RSEGS)) model) K.
