  Lemma seg_Gr : forall regs mem (pp : word) (A len : Z) K,
    g_regs regs pp A len -> (67108864 <= len < 2 ^ 62)%Z ->
    stk_ok RSEGS mem (Z_to_bv 64 (bv_unsigned sp0 - 128)) MSTK -> ro_none mem ->
    (forall regs' mem',
